async function ensureSeed(){
 let regions=await all('labor_regions');
 if(regions.length) return regions;
 const defs=[
  {id:'region-caba',name:'CABA y GBA',type:'base',factor:1,sourceLabel:'Referencias originales',prices:{aa:1,ei:1,epac:null}},
  {id:'region-catamarca',name:'Catamarca',type:'base',factor:1,sourceLabel:'Electro Instalador · Catamarca',sourceDate:'Febrero–marzo 2026',taxNote:'valores + IVA',prices:{aa:null,ei:null,epac:null},overrides:{'mo-56:ei':25800,'mo-57:ei':40400,'mo-58:ei':21200,'mo-59:ei':46500,'mo-60:ei':65400,'mo-61:ei':94600,'mo-64:ei':60200,'mo-65:ei':92400}},
  {id:'region-cordoba',name:'Córdoba',type:'base',factor:1,sourceLabel:'Electro Instalador · Córdoba / EPAC',sourceDate:'Octubre–diciembre 2026 / julio 2026',taxNote:'Electro Instalador: + IVA',prices:{aa:null,ei:null,epac:1},overrides:{'mo-58:ei':18500,'mo-21:ei':32500,'mo-62:ei':51000,'mo-63:ei':55000,'mo-64:ei':80000,'mo-71:ei':14500,'mo-72:ei':20000,'mo-66:ei':57000,'mo-67:ei':81000,'mo-68:ei':63500,'mo-69:ei':55000,'mo-70:ei':50000}},
  {id:'region-salta',name:'Salta',type:'base',factor:1,sourceLabel:'Electro Instalador · Salta',sourceDate:'Febrero–marzo 2025',taxNote:'valores + IVA',prices:{aa:null,ei:null,epac:null},overrides:{'mo-6:ei':18200,'mo-7:ei':15100,'mo-10:ei':12400,'mo-11:ei':12400}},
  {id:'region-chubut',name:'Chubut',type:'regional',factor:1.3,sourceLabel:'Referencias sectoriales y relevamientos de mercado',sourceDate:'Base septiembre / noviembre–diciembre 2026',prices:{aa:1.3,ei:1.3,epac:null}},
  {id:'region-rionegro',name:'Río Negro',type:'regional',factor:1.3,sourceLabel:'Referencias sectoriales y relevamientos de mercado',sourceDate:'Base septiembre / noviembre–diciembre 2026',prices:{aa:1.3,ei:1.3,epac:null}}
 ];
 for(const x of defs) await put('labor_regions',x);
 return defs;
}
function sourcePrice(item,region,source){const key=`${item.id}:${source}`;if(region.overrides&&Object.prototype.hasOwnProperty.call(region.overrides,key))return Number(region.overrides[key]);const base=item.prices[source];if(base==null||region.prices?.[source]==null)return null;return Math.round(base*region.prices[source]);}
function itemPrice(item,region){
 const manual=region.overrides?.[`${item.id}:avg`];
 if(manual!==undefined)return {value:Number(manual),refs:[{key:'custom',label:'Valor regional personalizado',value:Number(manual),date:'Modificado por el usuario'}],method:'Valor personalizado'};
 if(item.custom)return {value:Number(item.basePrice)||0,refs:[{key:'custom',label:'Ítem creado por el usuario',value:Number(item.basePrice)||0,date:'Precio definido manualmente'}],method:'Precio personalizado'};
 const aa=sourcePrice(item,region,'aa'),ei=sourcePrice(item,region,'ei'),epac=sourcePrice(item,region,'epac');
 // Promedio entre AAIERIC y Electro Instalador cuando existen ambos. EPAC
 // se utiliza como referencia alternativa cuando no hay ninguna de las dos.
 // La boca completa de AAIERIC es un precio publicado directamente. EI no
 // publica una boca completa equivalente: su desglose no se mezcla ni se
 // promedia automáticamente con el importe directo de AAIERIC.
 if(item.id==='mo-5' && aa!=null)return {value:aa,refs:[{key:'aa',label:sources.aa.name,value:aa,date:sources.aa.date}],method:'Referencia directa AAIERIC'};
 const refs=[...(aa!=null?[{key:'aa',label:sources.aa.name,value:aa,date:sources.aa.date}]:[]),...(ei!=null?[{key:'ei',label:sources.ei.name,value:ei,date:sources.ei.date}]:[])];
 if(refs.length)return {value:Math.round(refs.reduce((n,x)=>n+x.value,0)/refs.length),refs,method:refs.length>1?'Promedio simple de referencias publicadas':'Referencia publicada'};
 if(epac!=null)return {value:epac,refs:[{key:'epac',label:sources.epac.name,value:epac,date:sources.epac.date}],method:'Referencia publicada'};
 return null;
}
function cleanRegionalLabel(value){return String(value||'').replace(/\s*[·;]?\s*\+30%/g,'').replace(/\s{2,}/g,' ').trim();}
function regionInfo(region){
 const byId={
  'region-caba':{date:'Noviembre–diciembre 2026',refs:['AAIERIC · CABA y GBA (septiembre 2026)','Electro Instalador · listado nacional (noviembre–diciembre 2026)']},
  'region-catamarca':{date:'Febrero–marzo 2026',refs:['Electro Instalador · Catamarca (febrero–marzo 2026)']},
  'region-cordoba':{date:'Octubre–diciembre 2026',refs:['Electro Instalador · Córdoba (octubre–noviembre 2026)','EPAC · Córdoba (julio 2026)']},
  'region-salta':{date:'Febrero–marzo 2025',refs:['Electro Instalador · Salta (febrero–marzo 2025)']},
  'region-chubut':{date:'Noviembre–diciembre 2026',refs:['AAIERIC · CABA y GBA (septiembre 2026)','Electro Instalador · listado nacional (noviembre–diciembre 2026)']},
  'region-rionegro':{date:'Noviembre–diciembre 2026',refs:['AAIERIC · CABA y GBA (septiembre 2026)','Electro Instalador · listado nacional (noviembre–diciembre 2026)']}
 };
 if(byId[region.id])return byId[region.id];
 const refs=region.sourceRefs|| (region.sourceLabel?[region.sourceLabel]:['Lista personalizada']);
 return {date:region.sourceDate||'Sin fecha de referencia',refs:refs.map(cleanRegionalLabel)};
}
