 root.querySelector('#ml-pdf').onclick=()=>{list.title=root.querySelector('#ml-title').value.trim()||'Listado de materiales';list.clientName=displayClient(clients.find(c=>c.id===root.querySelector('#ml-client').value));list.notes=root.querySelector('#ml-notes').value;printMaterialList(list)};
 root.querySelector('#ml-link-quote').onclick=async()=>{if(!list.id)return alert('Guardá primero el listado para poder vincularlo a un presupuesto.');const q=(await all('labor_quotes')).find(x=>x.id===root.querySelector('#ml-quote').value);if(!q)return alert('Seleccioná un presupuesto.');if((list.clientId&&q.clientId&&list.clientId!==q.clientId)||(list.propertyId&&q.propertyId&&list.propertyId!==q.propertyId)||(list.jobId&&q.jobId&&list.jobId!==q.jobId))return alert('El presupuesto seleccionado no pertenece al mismo cliente, inmueble y trabajo del listado. Revisá las vinculaciones antes de copiar materiales.');if(!list.items.length)return alert('El listado está vacío.');q.items=q.items||[];for(const it of list.items)q.items.push({type:'material',materialId:it.materialId||null,name:it.name+(it.color?' · Color: '+it.color:''),unit:it.unit,quantity:it.quantity,unitPrice:Number(it.price)||0,sourceLabel:Number(it.price)>0?'Precio cargado en biblioteca':'Pendiente de cotización',standard:it.standard||''});q.updatedAt=new Date().toISOString();await put('labor_quotes',q);alert('Materiales incorporados al presupuesto. El listado original sigue independiente.')};
